/**
 * Markdown Link Extension
 *
 * Links a .md file to the session for collaborative editing.
 * Agent responses are appended to the file (viewable rendered in Obsidian).
 * User edits the file directly, then sends changes back via /send-diff.
 *
 * Commands:
 *   /link-md <filepath>  — Link a markdown file to this session
 *   /unlink-md           — Unlink the current file
 *   /send-diff (or /sd)  — Send your edits as a message to the agent
 */

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import * as fs from "node:fs";
import * as path from "node:path";

export default function (pi: ExtensionAPI) {
  let linkedFile: string | null = null;
  let lastKnownContent: string = "";

  // --- State restoration on session restart ---

  pi.on("session_start", async (_event, ctx) => {
    let lastLinkData: { file: string | null } | undefined;

    for (const entry of ctx.sessionManager.getEntries()) {
      if (entry.type === "custom" && entry.customType === "md-link") {
        lastLinkData = entry.data as { file: string | null } | undefined;
      }
    }

    if (lastLinkData?.file && fs.existsSync(lastLinkData.file)) {
      linkedFile = lastLinkData.file;
      lastKnownContent = fs.readFileSync(lastLinkData.file, "utf-8");
      const theme = ctx.ui.theme;
      ctx.ui.setStatus(
        "md-link",
        theme.fg("accent", "📄 ") + theme.fg("dim", path.basename(lastLinkData.file))
      );
    }
  });

  // --- Commands ---

  pi.registerCommand("link-md", {
    description: "Link a .md file for collaborative editing",
    handler: async (args, ctx) => {
      const filepath = args.trim();
      if (!filepath) {
        ctx.ui.notify("Usage: /link-md <filepath>", "warning");
        return;
      }

      const resolved = path.isAbsolute(filepath)
        ? filepath
        : path.resolve(ctx.cwd, filepath);

      // Create file + directories if needed
      if (!fs.existsSync(resolved)) {
        fs.mkdirSync(path.dirname(resolved), { recursive: true });
        fs.writeFileSync(resolved, "", "utf-8");
      }

      linkedFile = resolved;
      lastKnownContent = fs.readFileSync(resolved, "utf-8");
      pi.appendEntry("md-link", { file: resolved });

      const theme = ctx.ui.theme;
      ctx.ui.setStatus(
        "md-link",
        theme.fg("accent", "📄 ") + theme.fg("dim", path.basename(resolved))
      );
      ctx.ui.notify(`Linked: ${resolved}`, "success");
    },
  });

  pi.registerCommand("unlink-md", {
    description: "Unlink the current md file",
    handler: async (_args, ctx) => {
      if (!linkedFile) {
        ctx.ui.notify("No file linked", "warning");
        return;
      }
      const name = path.basename(linkedFile);
      linkedFile = null;
      lastKnownContent = "";
      pi.appendEntry("md-link", { file: null });
      ctx.ui.setStatus("md-link", undefined);
      ctx.ui.notify(`Unlinked: ${name}`, "info");
    },
  });

  // Shared handler for /send-diff and /sd
  const handleSendDiff = async (_args: string, ctx: any) => {
    if (!linkedFile) {
      ctx.ui.notify("No file linked. Use /link-md first.", "warning");
      return;
    }
    if (!ctx.isIdle()) {
      ctx.ui.notify("Wait for the agent to finish.", "warning");
      return;
    }
    if (!fs.existsSync(linkedFile)) {
      ctx.ui.notify(`File not found: ${linkedFile}`, "error");
      return;
    }

    const current = fs.readFileSync(linkedFile, "utf-8");
    if (current === lastKnownContent) {
      ctx.ui.notify("No changes detected.", "info");
      return;
    }

    const message = computeMessage(lastKnownContent, current);
    if (!message) {
      ctx.ui.notify("No meaningful changes.", "info");
      return;
    }

    lastKnownContent = current;
    pi.sendUserMessage(message);
  };

  pi.registerCommand("send-diff", {
    description: "Send your md file edits as a message",
    handler: handleSendDiff,
  });

  pi.registerCommand("sd", {
    description: "Alias for /send-diff",
    handler: handleSendDiff,
  });

  // --- Append assistant responses to linked file ---

  pi.on("message_end", async (event, _ctx) => {
    if (!linkedFile) return;

    const msg = event.message;
    if (!("role" in msg) || msg.role !== "assistant") return;

    // Skip intermediate messages that include tool calls —
    // only append the final text response
    const hasToolUse = msg.content.some((c: any) => c.type === "tool_use");
    if (hasToolUse) return;

    const textParts = msg.content
      .filter((c: any) => c.type === "text")
      .map((c: any) => (c.text as string).trim())
      .filter((t: string) => t.length > 0);

    if (textParts.length === 0) return;

    const text = textParts.join("\n\n");

    try {
      const current = fs.readFileSync(linkedFile, "utf-8");
      const prefix = current.trim().length > 0 ? "\n\n" : "";
      const updated = current + prefix + text + "\n\n---\n---\n";
      fs.writeFileSync(linkedFile, updated, "utf-8");
      lastKnownContent = updated;
    } catch {
      // File may have been deleted externally
    }
  });
}

// --- Diff computation ---

function computeMessage(oldContent: string, newContent: string): string | null {
  if (oldContent === newContent) return null;

  // Case 1: Simple append (most common — user wrote at the end)
  // This path sends the text exactly as-is, like typing in the TUI
  if (newContent.startsWith(oldContent)) {
    const appended = newContent.slice(oldContent.length).trim();
    return appended || null;
  }

  // Case 2: Inline edits — line-level diff
  const oldLines = oldContent.split("\n");
  const newLines = newContent.split("\n");

  // Find common prefix (identical lines from start)
  let start = 0;
  while (
    start < oldLines.length &&
    start < newLines.length &&
    oldLines[start] === newLines[start]
  ) {
    start++;
  }

  // Find common suffix (identical lines from end)
  let oldEnd = oldLines.length - 1;
  let newEnd = newLines.length - 1;
  while (
    oldEnd >= start &&
    newEnd >= start &&
    oldLines[oldEnd] === newLines[newEnd]
  ) {
    oldEnd--;
    newEnd--;
  }

  const removed = oldLines.slice(start, oldEnd + 1);
  const added = newLines.slice(start, newEnd + 1);

  if (removed.length === 0 && added.length === 0) return null;

  // Pure insertion (no lines removed) — send just the new text
  if (removed.length === 0) {
    return added.join("\n").trim() || null;
  }

  // Mixed changes (edits/replacements) — format with context
  const parts: string[] = [];

  // Add location context
  if (start > 0) {
    const ctx = oldLines[start - 1].trim().slice(0, 100);
    if (ctx) parts.push(`[After: "${ctx}"]`);
  }

  if (removed.length > 0) {
    parts.push("Removed:\n" + removed.join("\n"));
  }
  if (added.length > 0) {
    parts.push(
      (removed.length > 0 ? "Replaced with:\n" : "") + added.join("\n")
    );
  }

  return parts.join("\n\n").trim() || null;
}

/**
 * Persistent Project Memory Extension
 *
 * Maintains a MEMORY.md file as long-term project memory that the agent
 * reads at session start and updates throughout the session.
 *
 * - /memory or Alt+M to toggle on/off
 * - State persists per session
 * - When inactive, does nothing at all
 */

import type { ExtensionAPI, ExtensionContext } from "@mariozechner/pi-coding-agent";
import { Key } from "@mariozechner/pi-tui";
import { existsSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const CUSTOM_TYPE = "memory-state";
const MEMORY_FILE = "MEMORY.md";

const MEMORY_TEMPLATE = `# Project Memory

## Project Overview
<!-- What this project is and its goals -->

## Key Architecture / Decisions
<!-- Why things are the way they are -->

## Current State
<!-- What's in progress, what's done -->

## Notes / Gotchas
<!-- Things that bit us or are easy to forget -->

## Open Questions
<!-- Unresolved decisions -->
`;

const MEMORY_SYSTEM_PROMPT = `

## Persistent Memory

This project uses \`MEMORY.md\` as the long-term memory file.

- **At session start:** Read \`MEMORY.md\` silently before doing any work.
- **During the session:** Update \`MEMORY.md\` whenever you learn something worth remembering: architecture decisions, gotchas, file structure, tasks in progress, open questions.
- **At session end (if asked to wrap up):** Write a concise summary of what was done and what's next.
- Manage \`MEMORY.md\` autonomously — no asking permission.
- Keep entries concise. Prune stale entries.
`;

export default function memoryExtension(pi: ExtensionAPI) {
	let memoryEnabled = false;

	function updateStatus(ctx: ExtensionContext): void {
		if (memoryEnabled) {
			const theme = ctx.ui.theme;
			ctx.ui.setStatus("memory", theme.fg("accent", "🧠 Memory"));
		} else {
			ctx.ui.setStatus("memory", undefined);
		}
	}

	function ensureMemoryFile(cwd: string): void {
		const filePath = join(cwd, MEMORY_FILE);
		if (!existsSync(filePath)) {
			writeFileSync(filePath, MEMORY_TEMPLATE, "utf-8");
		}
	}

	function toggle(ctx: ExtensionContext): void {
		memoryEnabled = !memoryEnabled;
		pi.appendEntry(CUSTOM_TYPE, { enabled: memoryEnabled });

		if (memoryEnabled) {
			ensureMemoryFile(ctx.cwd);
			ctx.ui.notify("Memory enabled", "info");
		} else {
			ctx.ui.notify("Memory disabled", "info");
		}

		updateStatus(ctx);
	}

	pi.registerCommand("memory", {
		description: "Toggle persistent project memory (MEMORY.md)",
		handler: async (_args, ctx) => toggle(ctx),
	});

	pi.registerShortcut(Key.alt("m"), {
		description: "Toggle persistent project memory",
		handler: async (ctx) => toggle(ctx),
	});

	pi.on("session_start", async (_event, ctx) => {
		memoryEnabled = false;

		const entries = ctx.sessionManager.getEntries();
		for (let i = entries.length - 1; i >= 0; i--) {
			const entry = entries[i];
			if (entry.type === "custom" && entry.customType === CUSTOM_TYPE) {
				const data = entry.data as { enabled?: boolean } | undefined;
				memoryEnabled = data?.enabled ?? false;
				break;
			}
		}

		updateStatus(ctx);
	});

	pi.on("before_agent_start", async (event) => {
		if (!memoryEnabled) return undefined;

		return {
			systemPrompt: event.systemPrompt + MEMORY_SYSTEM_PROMPT,
		};
	});
}

/**
 * Read-only mode for pi.
 *
 * Usage:
 *   /read-only        -> toggle
 *   /read-only on     -> enable
 *   /read-only off    -> disable
 *   /read-only status -> show current state
 *
 * Notes:
 * - Hard-enforces a tiny tool allowlist: read, grep, find, ls
 * - Blocks every other tool call while enabled
 * - Re-registers the allowed tools with the built-in read-only implementations
 * - State is in-memory only and resets when pi restarts/reloads
 */
import type { ExtensionAPI, ExtensionContext } from "@mariozechner/pi-coding-agent";
import { createFindTool, createGrepTool, createLsTool, createReadTool } from "@mariozechner/pi-coding-agent";

const COMMAND_NAME = "read-only";
const STATUS_KEY = "read-only-mode";
const WIDGET_KEY = "read-only-mode";
const READ_ONLY_TOOL_NAMES = ["read", "grep", "find", "ls"] as const;

function getReadOnlyToolNames(pi: ExtensionAPI): string[] {
	const allToolNames = new Set(pi.getAllTools().map((tool) => tool.name));
	return READ_ONLY_TOOL_NAMES.filter((name) => allToolNames.has(name));
}

function updateUi(pi: ExtensionAPI, ctx: ExtensionContext, enabled: boolean): void {
	if (!enabled) {
		ctx.ui.setStatus(STATUS_KEY, undefined);
		ctx.ui.setWidget(WIDGET_KEY, undefined);
		return;
	}

	const tools = getReadOnlyToolNames(pi).join(", ");
	const theme = ctx.ui.theme;  
	ctx.ui.setStatus(STATUS_KEY, "🔒 read-only");

	ctx.ui.setWidget(WIDGET_KEY, [
		theme.fg("muted", `🔒 ${tools || "(none)"}`)
	]);
}

function applyReadOnlyTools(pi: ExtensionAPI): void {
	pi.setActiveTools(getReadOnlyToolNames(pi));
}

function restoreTools(pi: ExtensionAPI, toolsBeforeReadOnly?: string[]): void {
	const allToolNames = new Set(pi.getAllTools().map((tool) => tool.name));
	const toolNames = (toolsBeforeReadOnly ?? pi.getAllTools().map((tool) => tool.name)).filter((toolName) =>
		allToolNames.has(toolName),
	);
	pi.setActiveTools(toolNames);
}

export default function readOnlyModeExtension(pi: ExtensionAPI) {
	let enabled = false;
	let toolsBeforeReadOnly: string[] | undefined;

	const readTool = createReadTool(process.cwd());
	pi.registerTool({
		...readTool,
		async execute(toolCallId, params, signal, onUpdate, ctx) {
			return createReadTool(ctx.cwd).execute(toolCallId, params, signal, onUpdate);
		},
	});

	const grepTool = createGrepTool(process.cwd());
	pi.registerTool({
		...grepTool,
		async execute(toolCallId, params, signal, onUpdate, ctx) {
			return createGrepTool(ctx.cwd).execute(toolCallId, params, signal, onUpdate);
		},
	});

	const findTool = createFindTool(process.cwd());
	pi.registerTool({
		...findTool,
		async execute(toolCallId, params, signal, onUpdate, ctx) {
			return createFindTool(ctx.cwd).execute(toolCallId, params, signal, onUpdate);
		},
	});

	const lsTool = createLsTool(process.cwd());
	pi.registerTool({
		...lsTool,
		async execute(toolCallId, params, signal, onUpdate, ctx) {
			return createLsTool(ctx.cwd).execute(toolCallId, params, signal, onUpdate);
		},
	});

	function enableReadOnlyMode(ctx: ExtensionContext): void {
		if (enabled) {
			updateUi(pi, ctx, enabled);
			ctx.ui.notify("Read-only mode is already enabled.", "info");
			return;
		}

		enabled = true;
		toolsBeforeReadOnly = pi.getActiveTools();
		applyReadOnlyTools(pi);
		updateUi(pi, ctx, enabled);

		const tools = getReadOnlyToolNames(pi).join(", ");
		ctx.ui.notify(`Read-only mode enabled. Tools: ${tools || "(none)"}.`, "info");
	}

	function disableReadOnlyMode(ctx: ExtensionContext): void {
		if (!enabled) {
			updateUi(pi, ctx, enabled);
			ctx.ui.notify("Read-only mode is already disabled.", "info");
			return;
		}

		enabled = false;
		restoreTools(pi, toolsBeforeReadOnly);
		toolsBeforeReadOnly = undefined;
		updateUi(pi, ctx, enabled);
		ctx.ui.notify("Read-only mode disabled. Previous tool access restored.", "info");
	}

	function toggleReadOnlyMode(ctx: ExtensionContext): void {
		if (enabled) disableReadOnlyMode(ctx);
		else enableReadOnlyMode(ctx);
	}

	pi.registerCommand(COMMAND_NAME, {
		description: "Toggle hard-enforced read-only mode",
		getArgumentCompletions(prefix) {
			const actions = ["toggle", "on", "off", "status"];
			const items = actions
				.filter((action) => action.startsWith(prefix.toLowerCase()))
				.map((action) => ({ value: action, label: action }));
			return items.length > 0 ? items : null;
		},
		handler: async (args, ctx) => {
			const action = args.trim().toLowerCase();

			switch (action) {
				case "":
				case "toggle":
					toggleReadOnlyMode(ctx);
					return;
				case "on":
				case "enable":
					enableReadOnlyMode(ctx);
					return;
				case "off":
				case "disable":
					disableReadOnlyMode(ctx);
					return;
				case "status": {
					updateUi(pi, ctx, enabled);
					const tools = getReadOnlyToolNames(pi).join(", ");
					ctx.ui.notify(
						enabled
							? `Read-only mode is ON. Allowed tools: ${tools || "(none)"}.`
							: "Read-only mode is OFF.",
						"info",
					);
					return;
				}
				default:
					ctx.ui.notify(`Usage: /${COMMAND_NAME} [on|off|toggle|status]`, "warning");
			}
		},
	});

	pi.on("before_agent_start", async (event, ctx) => {
		if (!enabled) {
			updateUi(pi, ctx, enabled);
			return;
		}

		applyReadOnlyTools(pi);
		updateUi(pi, ctx, enabled);

		const tools = getReadOnlyToolNames(pi).join(", ") || "(none)";
		return {
			systemPrompt:
				event.systemPrompt +
				`\n\n[Read-only mode is active]\n` +
				`- You may only use these tools: ${tools}.\n` +
				`- You must not attempt any action that changes local files, processes, git state, dependencies, databases, remote systems, or any other external state.\n` +
				`- If the user asks for any write or side-effecting action, explain that read-only mode is enabled and tell them to run /${COMMAND_NAME} off first.`,
		};
	});

	pi.on("tool_call", async (event) => {
		if (!enabled) return;

		const allowedToolNames = new Set(getReadOnlyToolNames(pi));
		if (allowedToolNames.has(event.toolName)) return;

		return {
			block: true,
			reason:
				`Read-only mode is active. Tool "${event.toolName}" is blocked. ` +
				`Allowed tools: ${Array.from(allowedToolNames).join(", ") || "(none)"}. ` +
				`Use /${COMMAND_NAME} off to restore full tool access.`,
		};
	});

	pi.on("session_start", async (_event, ctx) => {
		if (enabled) applyReadOnlyTools(pi);
		updateUi(pi, ctx, enabled);
	});

	pi.on("session_switch", async (_event, ctx) => {
		if (enabled) applyReadOnlyTools(pi);
		updateUi(pi, ctx, enabled);
	});

	pi.on("session_fork", async (_event, ctx) => {
		if (enabled) applyReadOnlyTools(pi);
		updateUi(pi, ctx, enabled);
	});
}

{
  "name": "pi-bash-guard",
  "private": true,
  "type": "module",
  "dependencies": {
    "shell-quote": "^1.8.3"
  },
  "pi": {
    "extensions": ["./index.ts"]
  }
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { DynamicBorder, isToolCallEventType } from "@mariozechner/pi-coding-agent";
import type { SelectItem } from "@mariozechner/pi-tui";
import { Container, SelectList, Text } from "@mariozechner/pi-tui";
import { parse as shellParse } from "shell-quote";

type Severity = "high" | "medium";

type Risk = {
	severity: Severity;
	reasons: string[];
};

type OpToken = { op: string; [k: string]: unknown };

type Token = string | OpToken;

function isOpToken(t: Token): t is OpToken {
	return typeof t === "object" && t !== null && "op" in t;
}

function tokensToStrings(tokens: Token[]): string[] {
	return tokens.filter((t) => typeof t === "string") as string[];
}

function splitOnOps(tokens: Token[], splitOps: string[]): Token[][] {
	const out: Token[][] = [];
	let current: Token[] = [];
	for (const t of tokens) {
		if (isOpToken(t) && splitOps.includes(t.op)) {
			if (current.length) out.push(current);
			current = [];
			continue;
		}
		current.push(t);
	}
	if (current.length) out.push(current);
	return out;
}

function hasFlag(args: string[], flag: string): boolean {
	return args.includes(flag) || args.some((a) => a.startsWith(flag) && flag.length === 2 && a.startsWith("-"));
}

function anyArgStartsWith(args: string[], prefix: string): boolean {
	return args.some((a) => a.startsWith(prefix));
}

function analyzeSegment(seg: Token[]): Risk | null {
	const reasons: string[] = [];
	let severity: Severity = "medium";

	const ops = seg.filter(isOpToken).map((o) => o.op);
	const args = tokensToStrings(seg);
	if (args.length === 0) return null;

	const cmd = args[0];
	const rest = args.slice(1);

	// Shell redirection / pipes are handled on the whole command, but keep some segment checks too.
	if (ops.includes("|") && (args.includes("sh") || args.includes("bash") || args.includes("zsh") || args.includes("fish"))) {
		reasons.push("pipe to a shell (possible remote code execution)");
		severity = "high";
	}

	// sudo
	if (cmd === "sudo") {
		reasons.push("sudo (elevated privileges)");
		severity = "high";
	}

	// rm/rmdir/unlink
	if (cmd === "rm" || cmd === "rmdir" || cmd === "unlink") {
		severity = "high";
		reasons.push(`${cmd} (file deletion)`);
		if (rest.some((a) => a.includes("-r") || a.includes("-R"))) reasons.push("recursive delete (-r/-R)");
		if (rest.some((a) => a.includes("-f"))) reasons.push("forced delete (-f)");
		if (ops.includes("glob")) reasons.push("glob pattern expansion (may delete many files)");
	}

	// find -delete
	if (cmd === "find" && rest.includes("-delete")) {
		severity = "high";
		reasons.push("find -delete (bulk deletion)");
	}

	// git operations (prompt on ANY git command)
	if (cmd === "git") {
		const sub = rest[0];
		const subArgs = rest.slice(1);

		// Always prompt for git commands (user requested). Keep severity medium unless an explicit high-risk pattern is detected.
		reasons.push(sub ? `git ${sub} (git command)` : "git (git command)");

		if (sub === "rm") {
			severity = "high";
			reasons.push("git rm (deletes files from working tree and stages deletions)");
		}
		if (sub === "clean" && (subArgs.some((a) => a.includes("-f")) || subArgs.includes("-d") || subArgs.includes("-x"))) {
			severity = "high";
			reasons.push("git clean (can delete untracked files)");
		}
		if (sub === "reset" && subArgs.includes("--hard")) {
			severity = "high";
			reasons.push("git reset --hard (discard changes)");
		}
		if ((sub === "checkout" || sub === "restore") && (subArgs.includes(".") || subArgs.includes("--") || subArgs.includes("--source"))) {
			severity = severity === "high" ? "high" : "medium";
			reasons.push("git checkout/restore (can overwrite working tree)");
		}
		if (sub === "push" && (subArgs.includes("--force") || subArgs.includes("--force-with-lease") || subArgs.includes("-f"))) {
			severity = "high";
			reasons.push("git push --force (rewrite remote history)");
		}
		if (sub === "reflog" && subArgs.includes("expire")) {
			severity = "high";
			reasons.push("git reflog expire (can remove recovery history)");
		}
		if (sub === "gc" && subArgs.some((a) => a.startsWith("--prune"))) {
			severity = "high";
			reasons.push("git gc --prune (can permanently delete objects)");
		}
	}

	// truncate
	if (cmd === "truncate") {
		severity = severity === "high" ? "high" : "medium";
		reasons.push("truncate (in-place size change, can erase contents)");
	}

	// dd of=
	if (cmd === "dd" && (anyArgStartsWith(rest, "of=") || rest.includes("of"))) {
		severity = "high";
		reasons.push("dd with output file/device (can overwrite data)");
	}

	// Disk / volume management (prompt aggressively; high risk)
	// Linux: mkfs.*, wipefs, parted, fdisk, gdisk/sgdisk, lsblk, cryptsetup, LVM tools, zpool
	// macOS: diskutil, hdiutil, gpt, newfs_*, asr
	if (cmd.startsWith("mkfs")) {
		severity = "high";
		reasons.push("mkfs (filesystem formatting)");
	}
	if (cmd.startsWith("newfs_")) {
		severity = "high";
		reasons.push("newfs_* (filesystem formatting)");
	}
	if (cmd === "wipefs") {
		severity = "high";
		reasons.push("wipefs (disk signature wipe)");
	}
	if (cmd === "diskutil") {
		severity = "high";
		reasons.push("diskutil (disk management command)");
		if (rest.includes("eraseDisk") || rest.includes("eraseVolume")) {
			reasons.push("diskutil erase (destructive disk operation)");
		}
	}
	if (cmd === "hdiutil") {
		severity = "high";
		reasons.push("hdiutil (disk image management command)");
	}
	if (cmd === "gpt") {
		severity = "high";
		reasons.push("gpt (partition table manipulation)");
	}
	if (cmd === "asr") {
		severity = "high";
		reasons.push("asr (Apple Software Restore; can overwrite volumes)");
	}
	if (cmd === "parted" || cmd === "fdisk" || cmd === "gdisk" || cmd === "sgdisk") {
		severity = "high";
		reasons.push(`${cmd} (disk/partition management)`);
	}
	if (cmd === "lsblk") {
		// Usually read-only, but still disk-related; prompt as requested.
		severity = severity === "high" ? "high" : "medium";
		reasons.push("lsblk (disk listing)");
	}
	if (cmd === "cryptsetup") {
		severity = "high";
		reasons.push("cryptsetup (disk encryption management)");
	}
	if (cmd === "pvcreate" || cmd === "vgcreate" || cmd === "lvcreate") {
		severity = "high";
		reasons.push(`${cmd} (LVM volume management)`);
	}
	if (cmd === "zpool") {
		severity = "high";
		reasons.push("zpool (ZFS pool management)");
	}

	// chmod/chown recursive
	if (cmd === "chmod" && (rest.includes("-R") || rest.includes("--recursive"))) {
		severity = severity === "high" ? "high" : "medium";
		reasons.push("chmod -R (recursive permission changes)");
	}
	if (cmd === "chown" && (rest.includes("-R") || rest.includes("--recursive"))) {
		severity = severity === "high" ? "high" : "medium";
		reasons.push("chown -R (recursive ownership changes)");
	}

	// mv/cp overwriting
	if (cmd === "mv" && (rest.includes("-f") || rest.includes("--force"))) {
		severity = severity === "high" ? "high" : "medium";
		reasons.push("mv --force/-f (can overwrite files)");
	}
	if (cmd === "cp" && (rest.includes("-f") || rest.includes("--force"))) {
		severity = severity === "high" ? "high" : "medium";
		reasons.push("cp --force/-f (can overwrite files)");
	}

	// sed/perl in-place
	if (cmd === "sed" && (hasFlag(rest, "-i") || rest.includes("--in-place"))) {
		severity = severity === "high" ? "high" : "medium";
		reasons.push("sed -i (in-place file modification)");
	}
	if (cmd === "perl" && (rest.includes("-pi") || (rest.includes("-p") && rest.includes("-i")))) {
		severity = severity === "high" ? "high" : "medium";
		reasons.push("perl -pi/-i (in-place file modification)");
	}

	// kill/shutdown/systemctl
	if (cmd === "kill" || cmd === "pkill" || cmd === "killall") {
		severity = severity === "high" ? "high" : "medium";
		reasons.push(`${cmd} (process termination)`);
		if (rest.includes("-9")) {
			severity = "high";
			reasons.push("SIGKILL (-9)");
		}
	}
	if (cmd === "shutdown" || cmd === "reboot") {
		severity = "high";
		reasons.push(`${cmd} (system power operation)`);
	}
	if (cmd === "systemctl" && (rest.includes("stop") || rest.includes("disable"))) {
		severity = severity === "high" ? "high" : "medium";
		reasons.push("systemctl stop/disable (service disruption)");
	}

	// Remote execution patterns
	if ((cmd === "curl" || cmd === "wget") && ops.includes("|")) {
		severity = "high";
		reasons.push("curl/wget piped (possible remote code execution)");
	}

	// Infra deletes
	if (cmd === "kubectl" && rest[0] === "delete") {
		severity = "high";
		reasons.push("kubectl delete (resource deletion)");
	}
	if (cmd === "terraform" && rest[0] === "destroy") {
		severity = "high";
		reasons.push("terraform destroy (infrastructure teardown)");
	}
	if (cmd === "aws" && rest[0] === "s3" && rest[1] === "rm" && rest.includes("--recursive")) {
		severity = "high";
		reasons.push("aws s3 rm --recursive (bulk deletion)");
	}
	if (cmd === "gcloud" && rest.includes("delete")) {
		severity = "high";
		reasons.push("gcloud delete (resource deletion)");
	}

	if (reasons.length === 0) return null;
	return { severity, reasons };
}

function analyzeBashCommand(command: string): Risk | null {
	let tokens: Token[];
	try {
		tokens = shellParse(command) as Token[];
	} catch {
		// Fallback: if we can't parse, treat it as questionable
		return { severity: "medium", reasons: ["unparsed shell command (unable to analyze safely)"] };
	}

	const reasons: string[] = [];
	let severity: Severity = "medium";

	// Whole-command operator checks
	const ops = tokens.filter(isOpToken).map((t) => t.op);
	if (ops.some((op) => op === ">" || op === ">>" || op === "2>" || op === "2>>")) {
		reasons.push("shell output redirection (can overwrite files)");
		severity = severity === "high" ? "high" : "medium";
	}
	if (ops.includes("<")) {
		reasons.push("shell input redirection (questionable)");
	}
	if (ops.includes("|")) {
		reasons.push("pipe operator (chained commands)");
	}

	// Segment analysis (split on &&, ||, ;)
	const segments = splitOnOps(tokens, ["&&", "||", ";"]);
	for (const seg of segments) {
		const segRisk = analyzeSegment(seg);
		if (!segRisk) continue;
		if (segRisk.severity === "high") severity = "high";
		for (const r of segRisk.reasons) reasons.push(r);
	}

	// De-duplicate reasons
	const uniq = [...new Set(reasons)];
	if (uniq.length === 0) return null;
	return { severity, reasons: uniq };
}

async function promptRunOrAbort(ctx: any, command: string, risk: Risk): Promise<"run" | "abort"> {
	if (!ctx.hasUI) return "abort";

	const reasonsText = risk.reasons.map((r) => `• ${r}`).join("\n");
	const header = `Command flagged as ${risk.severity.toUpperCase()} risk:`;
	const body = `${header}\n\n${reasonsText}\n\nCommand:\n${command}`;

	const items: SelectItem[] = [
		{ value: "run", label: "Run", description: "Execute the command" },
		{ value: "abort", label: "Abort", description: "Block this command" },
	];

	const choice = await ctx.ui.custom<"run" | "abort">((tui, theme, _kb, done) => {
		const container = new Container();
		container.addChild(new DynamicBorder((s: string) => theme.fg("warning", s)));
		container.addChild(new Text(theme.fg("warning", theme.bold("Potentially destructive bash command")), 1, 0));
		container.addChild(new Text(body, 1, 0));

		const list = new SelectList(items, items.length, {
			selectedPrefix: (t) => theme.fg("accent", t),
			selectedText: (t) => theme.fg("accent", t),
			description: (t) => theme.fg("muted", t),
			scrollInfo: (t) => theme.fg("dim", t),
			noMatch: (t) => theme.fg("warning", t),
		});

		list.onSelect = (item) => done(item.value as "run" | "abort");
		list.onCancel = () => done("abort");
		container.addChild(list);

		container.addChild(new DynamicBorder((s: string) => theme.fg("warning", s)));

		return {
			render: (w) => container.render(w),
			invalidate: () => container.invalidate(),
			handleInput: (data) => {
				list.handleInput(data);
				tui.requestRender();
			},
		};
	}, { overlay: true });

	return choice ?? "abort";
}

// PI_SUBAGENT_DEPTH is 0 (or unset) in the main session and >= 1 in spawned subagent processes.
// Behaviour branches on this: interactive prompting in the main session, headless hard-block
// for catastrophic operations in subagents (where stdin is /dev/null and no UI is available).
const _subagentDepth = Number(process.env.PI_SUBAGENT_DEPTH ?? "0");
const _isSubagent = Number.isFinite(_subagentDepth) && _subagentDepth >= 1;

// Hard-block patterns for subagent (headless) mode. Criteria: unrecoverable by default AND
// unlikely to be intentional in an automated context. Fewer false positives over broad coverage —
// the interactive prompt handles the rest for main sessions.
const HEADLESS_BLOCKED: Array<{ pattern: RegExp; reason: string }> = [
	// Recursive deletion
	{ pattern: /(?<!\bgit\s+)\brm\b[^#\n]*\s-(?:[a-zA-Z]*[rR]|-\brecursive\b)/, reason: "recursive delete (rm -r / -rf / -Rf)" },
	// Privilege escalation
	{ pattern: /\bsudo\b/, reason: "elevated privileges (sudo)" },
	// Remote code execution via pipe-to-shell
	{ pattern: /\b(curl|wget)\b[^#\n]*\|\s*(ba?sh|zsh|fish|dash|sh)\b/, reason: "pipe to shell (remote code execution)" },
	// Disk / filesystem destruction
	{ pattern: /\bmkfs/, reason: "filesystem formatting (mkfs)" },
	{ pattern: /\bnewfs_\w+/, reason: "filesystem formatting (newfs_*)" },
	{ pattern: /\bwipefs\b/, reason: "disk signature wipe" },
	{ pattern: /\bdiskutil\s+(erase|zeroDisk|secureErase|reformat)/i, reason: "destructive disk operation (diskutil)" },
	{ pattern: /\bdd\b[^#\n]*\bof=\/dev\//, reason: "raw disk write (dd of=/dev/...)" },
	{ pattern: /\b(parted|fdisk|gdisk|sgdisk)\b/, reason: "partition table management" },
	{ pattern: /\bcryptsetup\b/, reason: "disk encryption management" },
	{ pattern: /\bzpool\b/, reason: "ZFS pool management" },
	// System power
	{ pattern: /\b(shutdown|reboot|halt|poweroff)\b/, reason: "system power operation" },
	// Infrastructure teardown
	{ pattern: /\bterraform\s+destroy\b/, reason: "infrastructure teardown (terraform destroy)" },
	{ pattern: /\bkubectl\s+delete\b/, reason: "Kubernetes resource deletion" },
	{ pattern: /\baws\s+s3\s+rm\b[^#\n]*--recursive/, reason: "bulk S3 deletion (aws s3 rm --recursive)" },
	// Destructive git operations
	{ pattern: /\bgit\s+commit\b/, reason: "git commit (commits are main-session operations)" },
	{ pattern: /\bgit\s+pull\b/, reason: "git pull (pulls are main-session operations)" },
	{ pattern: /\bgit\s+push\b/, reason: "git push (pushes are main-session operations)" },
	{ pattern: /\bgit\s+reset\b[^#\n]*--hard\b/, reason: "discard all uncommitted changes (git reset --hard)" },
	{ pattern: /\bgit\s+clean\b[^#\n]*-[a-zA-Z]*f/, reason: "delete untracked files (git clean -f)" },
	{ pattern: /\bgit\s+reflog\s+expire\b/, reason: "expire reflog (removes recovery history)" },
	{ pattern: /\bgit\s+gc\b[^#\n]*--prune\b/, reason: "prune unreachable objects (git gc --prune)" },
];

export default function (pi: ExtensionAPI) {
	if (_isSubagent) {
		// Subagent mode: hard-block catastrophic operations, no prompting.
		pi.on("tool_call", async (event) => {
			if (!isToolCallEventType("bash", event)) return;
			const command = event.input.command;
			for (const { pattern, reason } of HEADLESS_BLOCKED) {
				if (pattern.test(command)) {
					return {
						block: true,
						reason:
							`Blocked by bash-guard: ${reason}. ` +
							"This is a non-interactive subagent session — catastrophic operations are not permitted. " +
							"Propose a safer alternative or ask the parent agent to confirm with the user.",
					};
				}
			}
		});
		return;
	}

	// Main session mode: interactive prompting.
	pi.registerFlag("bash-guard-auto-allow", {
		description: "If set, bash-guard will not block when no UI is available (non-interactive modes).",
		type: "boolean",
		default: false,
	});

	// Avoid annoying retry loops: if the exact command was aborted recently, auto-block it.
	const recentlyAborted = new Map<string, number>();
	const ABORT_REMEMBER_MS = 60_000;

	pi.on("tool_call", async (event, ctx) => {
		if (!isToolCallEventType("bash", event)) return;

		const command = event.input.command;
		const risk = analyzeBashCommand(command);
		if (!risk) return;

		const now = Date.now();
		const lastAbort = recentlyAborted.get(command);
		if (lastAbort && now - lastAbort < ABORT_REMEMBER_MS) {
			return {
				block: true,
				reason:
					"Blocked by bash-guard: command was already aborted recently. Ask the user for a safer alternative; do not retry the same command.",
			};
		}

		if (!ctx.hasUI && pi.getFlag("--bash-guard-auto-allow")) {
			// Non-interactive mode: allow when explicitly requested.
			return;
		}

		const choice = await promptRunOrAbort(ctx, command, risk);
		if (choice === "run") return;

		recentlyAborted.set(command, now);
		return {
			block: true,
			reason:
				"Blocked by user via bash-guard (potentially destructive command). Ask the user for confirmation or propose a non-destructive alternative.",
		};
	});
}

{
  "name": "pi-filechanges",
  "private": true,
  "type": "module",
  "dependencies": {
    "diff": "^5.2.0"
  },
  "pi": {
    "extensions": ["./index.ts"]
  }
}

import type { ExtensionAPI, ExtensionCommandContext } from "@mariozechner/pi-coding-agent";
import {
	DynamicBorder,
	getMarkdownTheme,
	isEditToolResult,
	isToolCallEventType,
	isWriteToolResult,
} from "@mariozechner/pi-coding-agent";
import type { SelectItem } from "@mariozechner/pi-tui";
import { Container, Key, Markdown, SelectList, Text, matchesKey } from "@mariozechner/pi-tui";
import { createTwoFilesPatch } from "diff";
import { readFile, writeFile, rm, mkdir } from "node:fs/promises";
import { dirname, relative, resolve } from "node:path";

// Custom session entry types
// New name: filechanges
const ENTRY_BASELINE = "filechanges:baseline";
const ENTRY_CLEAR = "filechanges:clear";
const ENTRY_UNTRACK = "filechanges:untrack";

type Baseline = {
	path: string; // normalized path relative to ctx.cwd where possible
	absPath: string;
	originalContent: string | null; // null => file did not exist (created)
	createdAt: number;
};

type TrackedFile = {
	path: string;
	absPath: string;
	displayPath: string;
	originalContent: string | null;
	currentContent: string;
	diff: string;
	added: number;
	removed: number;
	kind: "new" | "edited";
	updatedAt: number;
};

type PendingSnapshot = {
	path: string;
	absPath: string;
	before: string | null;
};

function stripAtPrefix(p: string): string {
	return p.startsWith("@") ? p.slice(1) : p;
}

function normalizeToolPath(cwd: string, raw: string): { absPath: string; relPath: string } {
	const cleaned = stripAtPrefix(raw);
	const absPath = resolve(cwd, cleaned);
	// Use relative path for storage/UI when possible. If it escapes cwd, keep the cleaned input.
	const rel = relative(cwd, absPath);
	const relPath = rel && !rel.startsWith("..") && rel !== "" ? rel : cleaned;
	return { absPath, relPath };
}

async function readTextOrNull(absPath: string): Promise<string | null> {
	try {
		return await readFile(absPath, "utf-8");
	} catch {
		return null;
	}
}

function countDiffLines(unifiedDiff: string): { added: number; removed: number } {
	let added = 0;
	let removed = 0;
	for (const line of unifiedDiff.split("\n")) {
		if (line.startsWith("+++ ") || line.startsWith("--- ") || line.startsWith("@@")) continue;
		if (line.startsWith("+")) added++;
		else if (line.startsWith("-")) removed++;
	}
	return { added, removed };
}

function formatAddedRemovedPlain(added: number, removed: number): string {
	return `(+${added}/-${removed})`;
}


function styleAddedRemovedForList(theme: any, text: string): string {
	// File rows use "+x/-y" as description; other rows use normal sentences.
	const m = text.match(/^\+(\d+)\/\-(\d+)$/);
	if (!m) return theme.fg("muted", text);
	const added = Number(m[1]);
	const removed = Number(m[2]);

	const plus = added === 0 ? theme.fg("text", `+${added}`) : theme.fg("success", `+${added}`);
	const minus = removed === 0 ? theme.fg("text", `-${removed}`) : theme.fg("error", `-${removed}`);
	return plus + theme.fg("text", "/") + minus;
}

function formatStatus(tracked: Map<string, TrackedFile>, theme?: any): string | undefined {
	if (tracked.size === 0) return undefined;
	let edited = 0;
	let created = 0;
	for (const t of tracked.values()) {
		if (t.kind === "new") created++;
		else edited++;
	}
	if (!theme) {
			return `Δ ${edited}  + ${created}`;
		}
	return theme.fg("muted", `Δ ${edited}  + ${created}`);
}

function buildWidgetLines(tracked: Map<string, TrackedFile>, theme?: any): string[] | undefined {
	if (tracked.size === 0) return undefined;
	const items = [...tracked.values()].sort((a, b) => b.updatedAt - a.updatedAt);
	const max = 8;
	const lines: string[] = [];

	// Separator between chat history and this widget (widget renders above the editor).
	//const sep = "─".repeat(60);
	//lines.push(theme ? theme.fg("borderMuted", sep) : sep);

	for (const t of items.slice(0, max)) {
		const tag = t.kind === "new" ? "+" : "Δ";

		if (!theme) {
			lines.push(`${tag} ${t.displayPath} ${formatAddedRemovedPlain(t.added, t.removed)}`);
			continue;
		}

		const prefix = theme.fg("muted", `${tag} `) + theme.fg("muted", `${t.displayPath} `);
		let counts: string;
		const plus = t.added === 0 ? theme.fg("text", `+${t.added}`) : theme.fg("success", `+${t.added}`);
		const minus = t.removed === 0 ? theme.fg("text", `-${t.removed}`) : theme.fg("error", `-${t.removed}`);
		counts = theme.fg("text", "(") + plus + theme.fg("text", "/") + minus + theme.fg("text", ")");

		lines.push(prefix + counts);
	}
	if (items.length > max) {
		lines.push(theme ? theme.fg("dim", `…and ${items.length - max} more`) : `…and ${items.length - max} more`);
	}
	return lines;
}

function patchFromBaseline(displayPath: string, original: string | null, current: string): string {
	return createTwoFilesPatch(
		displayPath,
		displayPath,
		original ?? "",
		current,
		"",
		"",
		{ context: 3 }
	);
}

async function ensureParentDir(absPath: string): Promise<void> {
	await mkdir(dirname(absPath), { recursive: true });
}

export default function (pi: ExtensionAPI) {
	// In-memory state (reconstructed on session_start from custom entries)
	const baselines = new Map<string, Baseline>(); // key: relPath
	const tracked = new Map<string, TrackedFile>(); // key: relPath

	// Per-tool-call snapshot, only committed on successful tool_result
	const pendingByToolCallId = new Map<string, PendingSnapshot>();

	function updateUi(ctx: any) {
		if (!ctx?.hasUI) return;

		ctx.ui.setStatus("filechanges", formatStatus(tracked, ctx.ui.theme));
		ctx.ui.setWidget("filechanges", buildWidgetLines(tracked, ctx.ui.theme));
	}

	async function recomputeTrackedFile(ctx: any, relPath: string) {
		const baseline = baselines.get(relPath);
		if (!baseline) return;

		const current = await readTextOrNull(baseline.absPath);
		if (baseline.originalContent === null) {
			// file was created
			if (current === null) {
				tracked.delete(relPath);
				return;
			}
			const displayPath = baseline.path;
			const diff = patchFromBaseline(displayPath, null, current);
			const { added, removed } = countDiffLines(diff);
			tracked.set(relPath, {
				path: baseline.path,
				absPath: baseline.absPath,
				displayPath,
				originalContent: null,
				currentContent: current,
				diff,
				added,
				removed,
				kind: "new",
				updatedAt: Date.now(),
			});
			return;
		}

		// file existed before
		if (current === null) {
			// Deleted outside of tracked tools (or manually). Still track as edited; diff will show removal.
			const displayPath = baseline.path;
			const diff = patchFromBaseline(displayPath, baseline.originalContent, "");
			const { added, removed } = countDiffLines(diff);
			tracked.set(relPath, {
				path: baseline.path,
				absPath: baseline.absPath,
				displayPath,
				originalContent: baseline.originalContent,
				currentContent: "",
				diff,
				added,
				removed,
				kind: "edited",
				updatedAt: Date.now(),
			});
			return;
		}

		if (current === baseline.originalContent) {
			// back to original; untrack
			tracked.delete(relPath);
			return;
		}

		const displayPath = baseline.path;
		const diff = patchFromBaseline(displayPath, baseline.originalContent, current);
		const { added, removed } = countDiffLines(diff);
		tracked.set(relPath, {
			path: baseline.path,
			absPath: baseline.absPath,
			displayPath,
			originalContent: baseline.originalContent,
			currentContent: current,
			diff,
			added,
			removed,
			kind: "edited",
			updatedAt: Date.now(),
		});
	}

	async function clearLog(ctx: ExtensionCommandContext, reason: "accept" | "decline") {
		baselines.clear();
		tracked.clear();
		pendingByToolCallId.clear();
		pi.appendEntry(ENTRY_CLEAR, { timestamp: Date.now(), reason });
		updateUi(ctx);
	}

	async function declineAll(ctx: ExtensionCommandContext) {
		await ctx.waitForIdle();

		if (tracked.size === 0) {
			if (ctx.hasUI) ctx.ui.notify("filechanges: nothing to decline.", "info");
			return;
		}

		const force = (ctx as any).args?.includes("force") ?? false;
		if (ctx.hasUI && !force) {
			const ok = await ctx.ui.confirm(
				"Decline pi changes?",
				"This will revert ALL currently logged pi changes (overwrite files / delete created files)."
			);
			if (!ok) return;
		} else if (!ctx.hasUI && !force) {
			throw new Error("Decline requires confirmation. Run: /filechanges-decline force");
		}

		const items = [...tracked.values()].sort((a, b) => b.updatedAt - a.updatedAt);
		let reverted = 0;
		const errors: string[] = [];

		for (const item of items) {
			try {
				if (item.originalContent === null) {
					// created file
					await rm(item.absPath, { force: true });
				} else {
					await ensureParentDir(item.absPath);
					await writeFile(item.absPath, item.originalContent, "utf-8");
				}
				reverted++;
			} catch (e: any) {
				errors.push(`${item.displayPath}: ${e?.message ?? String(e)}`);
			}
		}

		await clearLog(ctx, "decline");

		if (ctx.hasUI) {
			if (errors.length === 0) {
				ctx.ui.notify(`filechanges: declined changes for ${reverted} file(s).`, "success");
			} else {
				ctx.ui.notify(
					`filechanges: declined with ${errors.length} error(s). Run /filechanges to inspect; see console for details.`,
					"warning"
				);
				console.warn("[filechanges] decline errors:\n" + errors.join("\n"));
			}
		}
	}

	async function acceptAll(ctx: ExtensionCommandContext) {
		await ctx.waitForIdle();

		if (tracked.size === 0) {
			if (ctx.hasUI) ctx.ui.notify("filechanges: nothing to accept.", "info");
			return;
		}

		const force = (ctx as any).args?.includes("force") ?? false;
		if (ctx.hasUI && !force) {
			const ok = await ctx.ui.confirm(
				"Accept pi changes?",
				"This will keep current files as-is and clear the modification log."
			);
			if (!ok) return;
		} else if (!ctx.hasUI && !force) {
			throw new Error("Accept requires confirmation. Run: /filechanges-accept force");
		}

		const count = tracked.size;
		await clearLog(ctx, "accept");
		if (ctx.hasUI) ctx.ui.notify(`filechanges: accepted changes for ${count} file(s).`, "success");
	}

	function parseCommandArgs(args: string | undefined): string[] {
		if (!args) return [];
		return args
			.split(/\s+/g)
			.map((s) => s.trim())
			.filter(Boolean);
	}

	// Commands
	pi.registerCommand("filechanges", {
		description: "Show files changed by pi and inspect diffs",
		handler: async (_args, ctx) => {
			// Provide args to helpers (a bit hacky but keeps code compact)
			(ctx as any).args = parseCommandArgs(_args);

			await ctx.waitForIdle();
			updateUi(ctx);

			if (!ctx.hasUI) {
				const items = [...tracked.values()].sort((a, b) => b.updatedAt - a.updatedAt);
				if (items.length === 0) {
					console.log("filechanges: no pi-made modifications recorded.");
					return;
				}
				// Non-interactive: just print a summary to stdout
				const lines = buildWidgetLines(tracked) ?? [];
				console.log(lines.join("\n"));
				return;
			}

			// Interactive loop: ESC in diff view returns to the modification log.
			while (true) {
				await ctx.waitForIdle();
				updateUi(ctx);

				const items = [...tracked.values()].sort((a, b) => b.updatedAt - a.updatedAt);
				if (items.length === 0) {
					ctx.ui.notify("filechanges: no pi-made modifications recorded.", "info");
					return;
				}

				const selectItems: SelectItem[] = [
					{ value: "__accept__", label: "Accept changes (clear log)", description: "Keep current files" },
					{ value: "__decline__", label: "Undo changes (revert)", description: "Restore original contents" },
					{ value: "__sep__", label: "────────", description: "" },
					...items.map((t) => ({
						value: t.path,
						label: `${t.kind === "new" ? "+" : "Δ"} ${t.displayPath}`,
						description: `+${t.added}/-${t.removed}`,
					})),
				];

				const picked = await ctx.ui.custom<string | null>((tui, theme, _kb, done) => {
					const container = new Container();
					container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));
					container.addChild(new Text(theme.fg("accent", theme.bold("File changes")), 1, 0));

					const list = new SelectList(selectItems, Math.min(14, selectItems.length), {
						selectedPrefix: (t) => theme.fg("accent", t),
						selectedText: (t) => theme.fg("accent", t),
						description: (t) => styleAddedRemovedForList(theme, t),
						scrollInfo: (t) => theme.fg("dim", t),
						noMatch: (t) => theme.fg("warning", t),
					});

					list.onSelect = (item) => {
						if (item.value === "__sep__") return;
						done(item.value);
					};
					list.onCancel = () => done(null);
					container.addChild(list);

					container.addChild(
						new Text(theme.fg("dim", "↑↓ navigate • enter select • esc close"), 1, 0)
					);
					container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));

					return {
						render: (w) => container.render(w),
						invalidate: () => container.invalidate(),
						handleInput: (data) => {
							list.handleInput(data);
							tui.requestRender();
						},
					};
				}, { overlay: true });

				if (!picked) return;
				if (picked === "__accept__") {
					await acceptAll(ctx);
					return;
				}
				if (picked === "__decline__") {
					await declineAll(ctx);
					return;
				}

				const t = tracked.get(picked);
				if (!t) {
					ctx.ui.notify("filechanges: entry not found (maybe log was cleared).", "warning");
					continue;
				}

				const md = "```diff\n" + (t.diff.trimEnd() || "(no diff)") + "\n```";
				await ctx.ui.custom<void>((tui, theme, _kb, done) => {
					const container = new Container();
					container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));
					container.addChild(new Text(theme.fg("accent", theme.bold(t.displayPath)), 1, 0));
					container.addChild(new Markdown(md, 1, 0, getMarkdownTheme()));
					container.addChild(new Text(theme.fg("dim", "esc to go back"), 1, 0));
					container.addChild(new DynamicBorder((s: string) => theme.fg("accent", s)));

					return {
						render: (w) => container.render(w),
						invalidate: () => container.invalidate(),
						handleInput: (data) => {
							if (matchesKey(data, Key.escape) || matchesKey(data, Key.ctrl("c"))) done();
							else tui.requestRender();
						},
					};
				}, { overlay: true });

				// After closing diff, loop back to the modification log.
			}
		},
	});

	pi.registerCommand("filechanges-accept", {
		description: "Accept pi-made changes (keeps files, clears log)",
		handler: async (args, ctx) => {
			(ctx as any).args = parseCommandArgs(args);
			await acceptAll(ctx);
		},
	});

	pi.registerCommand("filechanges-decline", {
		description: "Decline pi-made changes (reverts files, clears log)",
		handler: async (args, ctx) => {
			(ctx as any).args = parseCommandArgs(args);
			await declineAll(ctx);
		},
	});

	async function rebuildFromSession(ctx: any): Promise<void> {
		baselines.clear();
		tracked.clear();
		pendingByToolCallId.clear();

		// Replay custom entries on current branch
		for (const entry of ctx.sessionManager.getBranch()) {
			if (entry.type !== "custom") continue;

			if (entry.customType === ENTRY_CLEAR) {
				baselines.clear();
				tracked.clear();
				continue;
			}

			if (entry.customType === ENTRY_BASELINE) {
				const data = entry.data as any;
				if (!data?.path) continue;
				const { absPath, relPath } = normalizeToolPath(ctx.cwd, data.path);
				baselines.set(relPath, {
					path: relPath,
					absPath,
					originalContent: typeof data.originalContent === "string" ? data.originalContent : null,
					createdAt: typeof data.timestamp === "number" ? data.timestamp : Date.now(),
				});
				continue;
			}

			if (entry.customType === ENTRY_UNTRACK) {
				const data = entry.data as any;
				if (!data?.path) continue;
				const { relPath } = normalizeToolPath(ctx.cwd, data.path);
				baselines.delete(relPath);
				tracked.delete(relPath);
				continue;
			}
		}

		// Compute current diffs
		for (const relPath of baselines.keys()) {
			await recomputeTrackedFile(ctx, relPath);
		}

		updateUi(ctx);
	}

	// Rebuild state on any session/branch navigation events
	pi.on("session_start", async (_event, ctx) => {
		await rebuildFromSession(ctx);
	});

	pi.on("session_switch", async (_event, ctx) => {
		await rebuildFromSession(ctx);
	});

	pi.on("session_tree", async (_event, ctx) => {
		await rebuildFromSession(ctx);
	});

	pi.on("session_fork", async (_event, ctx) => {
		await rebuildFromSession(ctx);
	});

	// Capture before snapshots for edit/write
	pi.on("tool_call", async (event, ctx) => {
		if (isToolCallEventType("edit", event) || isToolCallEventType("write", event)) {
			const { absPath, relPath } = normalizeToolPath(ctx.cwd, event.input.path);
			const before = await readTextOrNull(absPath);
			pendingByToolCallId.set(event.toolCallId, { path: relPath, absPath, before });
		}
	});

	// Commit on successful results
	pi.on("tool_result", async (event, ctx) => {
		if (event.isError) {
			pendingByToolCallId.delete(event.toolCallId);
			return;
		}

		if (!isEditToolResult(event) && !isWriteToolResult(event)) return;

		const pending = pendingByToolCallId.get(event.toolCallId);
		pendingByToolCallId.delete(event.toolCallId);
		if (!pending) return;

		// If no baseline exists yet for this file, create one now from the successful call's snapshot.
		if (!baselines.has(pending.path)) {
			baselines.set(pending.path, {
				path: pending.path,
				absPath: pending.absPath,
				originalContent: pending.before,
				createdAt: Date.now(),
			});
			pi.appendEntry(ENTRY_BASELINE, {
				path: pending.path,
				originalContent: pending.before,
				timestamp: Date.now(),
			});
		}

		// Recompute cumulative diff against baseline
		await recomputeTrackedFile(ctx, pending.path);

		// If file is back to baseline, untrack + persist
		const baseline = baselines.get(pending.path);
		const current = await readTextOrNull(pending.absPath);
		if (baseline) {
			const backToOriginal =
				(baseline.originalContent !== null && current === baseline.originalContent) ||
				(baseline.originalContent === null && current === null);

			if (backToOriginal) {
				baselines.delete(pending.path);
				tracked.delete(pending.path);
				pi.appendEntry(ENTRY_UNTRACK, { path: pending.path, timestamp: Date.now() });
			}
		}

		updateUi(ctx);
	});
}

import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { Type } from "typebox";
import * as fs from "node:fs";
import * as path from "node:path";

/**
 * Google Image Search Extension
 *
 * Registers a `google_image_search` tool that uses the Google Custom Search
 * JSON API to search for images and return structured metadata including
 * inline thumbnails for visual selection.
 *
 * Credentials: auth.json in this extension directory with
 * { "google_search_api_key": "...", "google_cse_id": "..." }
 */

const EXT_DIR = path.dirname(new URL(import.meta.url).pathname);
const AUTH_PATH = path.join(EXT_DIR, "auth.json");

function loadCredentials(): { apiKey: string; cseId: string } | null {
	const envApiKey = process.env.GOOGLE_SEARCH_API_KEY ?? process.env.GOOGLE_API_KEY;
	const envCseId = process.env.GOOGLE_CSE_ID ?? process.env.GOOGLE_CUSTOM_SEARCH_ENGINE_ID;
	if (envApiKey && envCseId) return { apiKey: envApiKey, cseId: envCseId };

	if (!fs.existsSync(AUTH_PATH)) return null;
	try {
		const config = JSON.parse(fs.readFileSync(AUTH_PATH, "utf-8"));
		const apiKey = config.google_search_api_key as string;
		const cseId = config.google_cse_id as string;
		if (apiKey && cseId) return { apiKey, cseId };
	} catch {}
	return null;
}
export default function activate(pi: ExtensionAPI) {
	pi.registerTool({
		name: "google_image_search",
		label: "Google Image Search",

		description:
			"Search Google Images using the Custom Search API. " +
			"Returns image URLs, inline thumbnails, titles, and source domains.",

		promptSnippet: "Search Google Images and return structured metadata (URL, thumbnail, title, source domain)",

		parameters: Type.Object({
			query: Type.String({
				description: "Image search query",
			}),
			max_results: Type.Optional(
				Type.Number({
					description: "Maximum number of results to return (1-10, default 5).",
					minimum: 1,
					maximum: 10,
				})
			),
		}),

		async execute(_toolCallId, params, _signal, _onUpdate, _ctx) {
			const query = params.query as string;
			const maxResults = Math.round(Math.min(Math.max((params.max_results as number | undefined) ?? 5, 1), 10));

			const creds = loadCredentials();
			if (!creds) {
				return {
					content: [{ type: "text", text: `Error: Missing Google Custom Search credentials. Set GOOGLE_SEARCH_API_KEY and GOOGLE_CSE_ID, or create ${AUTH_PATH} from auth.example.json. Get credentials from https://developers.google.com/custom-search/v1/introduction` }]
				};
			}
			const { apiKey, cseId } = creds;

			try {
				const results = await searchGoogleImages(query, maxResults, apiKey, cseId);
				if (results.length === 0) {
					return {
						content: [{ type: "text", text: `No images found for query: ${query}` }]
					};
				}

				// Fetch all thumbnails in parallel
				const thumbnails = await fetchThumbnails(results);

				// Build interleaved image + text content blocks
				const content: Array<{ type: "text"; text: string } | { type: "image"; data: string; mimeType: string }> = [];
				for (let i = 0; i < results.length; i++) {
					const r = results[i];
					const thumb = thumbnails[i];
					if (thumb) {
						content.push({ type: "image", data: thumb.data, mimeType: thumb.mimeType });
					}
					content.push({ type: "text", text: `[${i + 1}] Title: ${r.title}\nURL: ${r.url}\nSource: ${r.source_domain}` });
				}

				return {
					content,
					details: { results, query }
				};
			} catch (err: unknown) {
				const msg = err instanceof Error ? err.message : String(err);
				return {
					content: [{ type: "text", text: `Error: Google Image Search failed: ${msg}` }]
				};
			}
		},
	});
}

interface ImageResult {
	url: string;
	thumbnail_url: string;
	title: string;
	source_domain: string;
}

async function fetchThumbnails(
	results: ImageResult[],
): Promise<Array<{ data: string; mimeType: string } | null>> {
	return Promise.all(
		results.map(async (r) => {
			try {
				const resp = await fetch(r.thumbnail_url, {
					signal: AbortSignal.timeout(5000),
				});
				if (!resp.ok) return null;
				const contentType = resp.headers.get("content-type") || "";
				if (!contentType.startsWith("image/")) return null;
				const buf = Buffer.from(await resp.arrayBuffer());
				return { data: buf.toString("base64"), mimeType: contentType.split(";")[0] };
			} catch {
				return null;
			}
		}),
	);
}

async function searchGoogleImages(
	query: string,
	maxResults: number,
	apiKey: string,
	cseId: string
): Promise<ImageResult[]> {
	const num = Math.min(maxResults, 10);
	const url = new URL("https://www.googleapis.com/customsearch/v1");
	url.searchParams.set("key", apiKey);
	url.searchParams.set("cx", cseId);
	url.searchParams.set("q", query);
	url.searchParams.set("searchType", "image");
	url.searchParams.set("num", String(num));

	const resp = await fetch(url.toString());
	if (!resp.ok) {
		const body = await resp.text();
		throw new Error(`HTTP ${resp.status}: ${body.slice(0, 200)}`);
	}

	const data = (await resp.json()) as {
		items?: Array<{
			link: string;
			title: string;
			displayLink: string;
			image?: { thumbnailLink?: string };
		}>;
	};

	if (!data.items || data.items.length === 0) {
		return [];
	}

	return data.items.map((item) => ({
		url: item.link,
		thumbnail_url: item.image?.thumbnailLink ?? item.link,
		title: item.title,
		source_domain: item.displayLink,
	}));
}

